{"path":"src/shipping.py","content":"from decimal import Decimal, ROUND_HALF_UP


def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The cost consists of a EUR 4.00 base fee and a EUR 1.75 charge for
    each kilogram. Express delivery doubles the resulting total. The final
    amount is rounded to two decimal places using normal monetary rounding.
    """
    weight = Decimal(str(weight_kg))
    total = Decimal("4.00") + Decimal("1.75") * weight
    if express:
        total *= 2
    return float(total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
